import{_ as l,o as a,c as i,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Ceph Performance Meeting 2023-01-26","description":"","frontmatter":{"title":"Ceph Performance Meeting 2023-01-26","date":"2023-01-26T00:00:00.000Z","updated":"2023-02-01T00:00:00.000Z","tags":["Ceph","分布式存储","性能优化","延迟问题","写放大问题"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Ceph_Performance_Meeting_2023-01-26.md","filePath":"posts/2023/Ceph_Performance_Meeting_2023-01-26.md","lastUpdated":1780460162000}'),r={name:"posts/2023/Ceph_Performance_Meeting_2023-01-26.md"};function o(n,e,s,h,p,d){return a(),i("div",null,[...e[0]||(e[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ol><li><p><strong>Etherpad 归档问题</strong>：</p><ul><li>每年将 Etherpad 内容归档到前一年文档中，发现2021年记录丢失，原因是服务器端复制粘贴操作失败。</li><li>通过调整服务器缓冲区大小，解决了未来可能发生的类似问题。</li></ul></li><li><p><strong>新Pull Request讨论</strong>：</p><ul><li>Igor 提交的两个新 PR： <ul><li>第一个 PR 涉及多块读取时不重置预取缓冲区，讨论了性能统计改进，但实际性能提升不明显。</li><li>第二个 PR 关于在飞行中启用 RocksDB 删除操作，讨论了实验应用和潜在改进。</li></ul></li><li>讨论其他 PR，包括启用4K分配单元、用户边界迭代器等，评估其对性能的影响和后续 QA 需求。</li></ul></li><li><p><strong>延迟峰值问题</strong>：</p><ul><li>升级到 Pacific 版本后出现的延迟峰值问题，确定是由消息传递层的 throttle 机制导致。</li><li>通过调整或禁用 throttle 机制优化性能。</li></ul></li><li><p><strong>写放大问题</strong>：</p><ul><li>通过 perf dump 数据分析，发现升级到 Pacific 后，写操作的平均大小有所增加。</li><li>讨论可能原因，包括碎片化和元数据增加，但尚未找到确切原因。</li><li>提出进一步分析 RocksDB 日志和监控数据的建议。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>调整 Etherpad 归档流程，确保数据安全性和完整性。</li><li>继续审查和测试新的 Pull Request。</li><li>解决延迟峰值问题，优化性能。</li><li>进一步分析写放大问题，寻找根本原因并提出解决方案。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>完成对新 PR 的审查和测试。</li><li>监控和分析延迟峰值问题，确保配置和配置已优化。</li><li>深入分析写放大问题，确定问题的根本原因并提出解决方案。</li><li>定期回顾和更新 Etherpad 归档流程。</li></ul><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h3><p>本次会议讨论了多个关键议题，包括 Etherpad 归档问题、新 Pull Request 的审查、延迟峰值问题和写放大问题。通过讨论，团队确定了后续行动计划，并将继续监控和优化系统性能。</p>',9)])])}const _=l(r,[["render",o]]);export{c as __pageData,_ as default};
